CREATE TABLE revenue_transactions(id BINARY(16) PRIMARY KEY,idempotency_key VARCHAR(255) NOT NULL UNIQUE,client_id BINARY(16) NOT NULL,game_id BINARY(16) NOT NULL,amount DECIMAL(19,6) NOT NULL,currency CHAR(3) NOT NULL,occurred_at TIMESTAMP(6) NOT NULL,recorded_at TIMESTAMP(6) NOT NULL);
CREATE TABLE revenue_allocations(id BINARY(16) PRIMARY KEY,transaction_id BINARY(16) NOT NULL,beneficiary_id BINARY(16) NOT NULL,beneficiary_type VARCHAR(30) NOT NULL,amount DECIMAL(19,6) NOT NULL,FOREIGN KEY(transaction_id) REFERENCES revenue_transactions(id));
CREATE TABLE adjustments(id BINARY(16) PRIMARY KEY,idempotency_key VARCHAR(255) NOT NULL UNIQUE,original_transaction_id BINARY(16) NOT NULL,amount_delta DECIMAL(19,6) NOT NULL,reason VARCHAR(255) NOT NULL,created_by BINARY(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(original_transaction_id) REFERENCES revenue_transactions(id));
CREATE TABLE settlements(id BINARY(16) PRIMARY KEY,beneficiary_id BINARY(16) NOT NULL,period_from DATE NOT NULL,period_to DATE NOT NULL,amount DECIMAL(19,6) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMP(6) NOT NULL);